#!/usr/bin/env perl
# Usage:
#   perl cld_extract.pl [--template dialogue.csv] input.cld [output_folder]
#
#   --template  A dialogue.csv generated by the user's own Translator.exe (Create -> CSV).
#               The CLD translations are filled into it by ID, so the layout, order,
#               speakers and English column stay exactly as the official tool made them.
#   (no option) A CSV in the same layout is generated from the CLD alone. The English
#               column is empty and the sections are flat (labelLUT / linesLUT).
#               The official build tool will not accept it, but cld_repack.pl will.
use strict;
use warnings;

use JSON::PP qw(decode_json);
use MIME::Base64 qw(decode_base64);
use File::Path qw(make_path);
use File::Basename qw(dirname);
use Getopt::Long;
use Text::CSV;

my $template;
GetOptions('template=s' => \$template)
    or die "Usage: perl cld_extract.pl [--template dialogue.csv] input.cld [output_folder]\n";

my $input = shift
    or die "Usage: perl cld_extract.pl [--template dialogue.csv] input.cld [output_folder]\n";
my $root = shift // '.';

open my $in, '<:raw', $input or die "Failed to open input file: $!\n";
my $data = do { local $/; <$in> };
close $in;

# Remove the LANGDATA prefix at the beginning of the file
$data =~ s/\ALANGDATA\s*//;

my $json = eval { decode_json($data) };
die "JSON parsing failed: $@" if $@;
die "The top-level data is not a JSON object.\n"
    unless ref($json) eq 'HASH';

sub make_parent_dir {
    my ($path) = @_;
    my $dir = dirname($path);
    make_path($dir) unless -d $dir;
}

sub decode_b64 {
    my ($value) = @_;
    $value =~ s/\Adata:[^,]*,//;
    return decode_base64($value);
}

# ==================================================
# imgFiles: Save Base64 images by path
# ==================================================

if (ref($json->{imgFiles}) eq 'HASH') {

    for my $path (sort keys %{$json->{imgFiles}}) {

        if ($path =~ m{^[/\\]}
            || $path =~ m{(?:^|[/\\])\.\.(?:[/\\]|$)}) {

            warn "Skipping unsafe image path: $path\n";
            next;
        }

        my $value = $json->{imgFiles}{$path};

        unless (defined $value && !ref($value)) {
            warn "Skipping image because its data is not a string: $path\n";
            next;
        }

        my $bytes = decode_b64($value);

        my $ext = '.bin';

        if (substr($bytes, 0, 8) eq "\x89PNG\r\n\x1a\n") {
            $ext = '.png';
        }
        elsif (substr($bytes, 0, 3) eq "\xFF\xD8\xFF") {
            $ext = '.jpg';
        }
        elsif (substr($bytes, 0, 4) eq 'RIFF'
            && substr($bytes, 8, 4) eq 'WEBP') {
            $ext = '.webp';
        }

        my $out_path = "$root/$path$ext";

        make_parent_dir($out_path);

        open my $img, '>:raw', $out_path
            or do {
                warn "Failed to save image ($out_path): $!\n";
                next;
            };

        print {$img} $bytes;
        close $img;

        print "Image saved: $out_path\n";
    }
}

# ==================================================
# fontFile: Save the font using the fontFace name
# ==================================================

if (defined $json->{fontFile}
    && !ref($json->{fontFile})
    && length $json->{fontFile}) {

    my $bytes = decode_b64($json->{fontFile});

    my $ext = '.bin';
    my $signature = substr($bytes, 0, 4);

    if ($signature eq 'OTTO') {
        $ext = '.otf';
    }
    elsif ($signature eq "\x00\x01\x00\x00"
        || $signature eq 'true') {
        $ext = '.ttf';
    }

    my $font_name = $json->{fontFace} // 'font';

    $font_name =~ s/[\/\\:*?"<>|]/_/g;
    $font_name =~ s/^\.+//;
    $font_name = 'font' if $font_name eq '';

    my $font_path = "$root/font/$font_name$ext";

    make_parent_dir($font_path);

    open my $font, '>:raw', $font_path
        or die "Failed to save font ($font_path): $!\n";

    print {$font} $bytes;
    close $font;

    print "Font saved: $font_path\n";
}
else {
    warn "fontFile data is missing or empty.\n";
}

# ==================================================
# CSV in the dialogue.csv layout
# ==================================================
#
# CLD key      -> CSV section
#   langName / fontFace / fontSize -> first info row
#   langInfo                       -> credits row
#   sysLabel                       -> Labels
#   sysMenus                       -> Menus
#   labelLUT                       -> Speakers / Items   (ID -> string)
#   linesLUT                       -> Descriptions / dialogue (ID -> array of lines)

my $csv_path = "$root/dialogue.csv";

if (defined $template) {
    my ($tp, $op) = map { my $p = $_; $p =~ s{\\}{/}g; $p } ($template, $csv_path);
    die "The output CSV would overwrite the template ($template). Choose another output folder.\n"
        if $tp eq $op;
}

make_parent_dir($csv_path);

my $sys_label = ref($json->{sysLabel}) eq 'HASH' ? $json->{sysLabel} : {};
my $sys_menus = ref($json->{sysMenus}) eq 'HASH' ? $json->{sysMenus} : {};
my $label_lut = ref($json->{labelLUT}) eq 'HASH' ? $json->{labelLUT} : {};
my $lines_lut = ref($json->{linesLUT}) eq 'HASH' ? $json->{linesLUT} : {};
my $lang_info = ref($json->{langInfo}) eq 'ARRAY' ? $json->{langInfo} : [];

my $csv = Text::CSV->new({ binary => 1, auto_diag => 1, eol => "\n" });

open my $out, '>:encoding(UTF-8)', $csv_path
    or die "Failed to open CSV file ($csv_path): $!\n";

sub emit {
    my @row = map { defined $_ ? "$_" : '' } @_;
    push @row, '' while @row < 4;
    $csv->print($out, \@row);
}

# CLD value -> list of lines. One CSV row is written per line (official "consecutive rows" style).
sub lines_list {
    my ($v) = @_;
    return [''] unless defined $v;
    return [ map { defined $_ ? "$_" : '' } @$v ] if ref($v) eq 'ARRAY';
    return [ ref($v) ? '' : "$v" ];
}

# Merge several English cells into one. No extra space is added when the boundary
# already has whitespace (e.g. "... And it's " + "only for ...").
sub join_english {
    my @parts = grep { defined } @_;
    my $s = shift @parts;
    return '' unless defined $s;
    for my $t (@parts) {
        my $glue = (!length($s) || !length($t) || $s =~ /\s\z/ || $t =~ /\A\s/) ? '' : ' ';
        $s .= $glue . $t;
    }
    return $s;
}

sub info_rows {
    emit('Language', 'Font File', 'Font Size');
    emit($json->{langName}, $json->{fontFace}, $json->{fontSize});
    emit();
    emit('Credit 1', 'Credit 2', 'Credit 3');
    emit(map { $lang_info->[$_] } 0 .. 2);
    emit();
}

if (defined $template) {

    # ---------- Mode A: fill the user's own dialogue.csv ----------
    # Rows are recognised by their HEADER row (a row containing "Translation"), not by blank rows or
    # "Section" markers, so unknown section layouts (e.g. Map*.json) still get filled.
    my (%used, %missing, %stat, @ambiguous, %sec_total, %sec_empty, %miss_src, @miss_ids);

    my $lines_for = sub {                  # ID -> arrayref of lines (or undef)
        my ($id) = @_;
        return undef unless exists $lines_lut->{$id};
        $used{lines}{$id} = 1;
        my $l = lines_list($lines_lut->{$id});
        return @$l ? $l : undef;
    };
    my $label_for = sub {
        my ($id) = @_;
        return undef unless exists $label_lut->{$id};
        $used{labels}{$id} = 1;
        return $label_lut->{$id};
    };
    my $trim = sub { my ($x) = @_; $x = '' unless defined $x; $x =~ s/\A\s+|\s+\z//g; $x };

    # ---- pass 1: read the template and tag every row with its section type
    my $tcsv = Text::CSV->new({ binary => 1, auto_diag => 1 });
    open my $tfh, '<:encoding(UTF-8)', $template
        or die "Failed to open template ($template): $!\n";

    my (@T, $bom);
    my ($expect, $first, $sec, $hdr) = ('', 1, '', undef);

    while (my $r = $tcsv->getline($tfh)) {
        my @r = map { defined $_ ? $_ : '' } @$r;

        if ($first) {                      # UTF-8 BOM
            $first = 0;
            $bom = 1 if $r[0] =~ s/\A\x{FEFF}//;
        }
        
        if ($expect) {                     # value row after the "Language..." / "Credit 1..." header
            push @T, { r => \@r, st => $expect };
            $expect = '';
            next;
        }

        unless (grep { length } @r) {      # blank row
            ($expect, $hdr) = ('', undef);
            push @T, { r => \@r, st => '' };
            next;
        }

        my ($c0, $c1) = ($trim->($r[0]), $trim->($r[1]));

        if ($c0 eq 'Language' && $c1 eq 'Font File') { $expect = 'info1'; push @T, { r => \@r, st => '' }; next }
        if ($c0 eq 'Credit 1')                       { $expect = 'info2'; push @T, { r => \@r, st => '' }; next }
        if ($c0 eq 'Section')                        { ($hdr, $sec) = (undef, $c1); push @T, { r => \@r, st => '' }; next }

        # Header row: has a "Translation" cell and an "English" cell (or is the Menus / ID header)
        my ($ti) = grep { $trim->($r[$_]) eq 'Translation' } 0 .. $#r;
        my ($ei) = grep { $trim->($r[$_]) eq 'English' }     0 .. $#r;
        if (defined $ti && (defined $ei || $c0 eq 'Menus' || $c0 eq 'ID')) {
            my $st = $c0 eq 'Labels'                         ? 'labels'
                   : $c0 eq 'Menus'                          ? 'menus'
                   : ($c0 eq 'Speakers' || $c0 eq 'Items')   ? 'lbl'
                   : $c0 eq 'Descriptions'                   ? 'desc'
                   :                                           'dlg';
            $hdr = { st => $st, col => $ti, ecol => (defined $ei ? $ei : $ti - 1) };
            $sec = $c0 unless $c0 eq 'ID';
            push @T, { r => \@r, st => '' };
            next;
        }

        if ($hdr) { push @T, { r => \@r, st => $hdr->{st}, col => $hdr->{col}, ecol => $hdr->{ecol}, id => $c0, sec => $sec } }
        else      { push @T, { r => \@r, st => '' } }                 # stray row: written back unchanged
    }
    close $tfh;

    # ---- pass 2: write the filled rows
    print {$out} "\x{FEFF}" if $bom;

    for (my $i = 0; $i < @T; ) {
        my $t  = $T[$i];
        my $st = $t->{st};
        my @r  = @{ $t->{r} };

        if ($st eq 'info1') {
            @r[0, 1, 2] = map { defined $_ ? $_ : '' } @$json{qw(langName fontFace fontSize)};
        }
        elsif ($st eq 'info2') {
            $r[$_] = $lang_info->[$_] // '' for 0 .. 2;
        }
        elsif ($st eq 'labels' || $st eq 'menus' || $st eq 'lbl') {
            my ($c, $id) = ($t->{col}, $t->{id});
            my $val = $st eq 'labels' ? $sys_label->{$id}
                    : $st eq 'menus'  ? $sys_menus->{$id}
                    :                   $label_for->($id);
            push @r, '' while @r <= $c;
            $sec_total{ $t->{sec} }++;
            if (defined $val) { $r[$c] = $val }
            else              { $r[$c] = ''; $missing{$st}++; $sec_empty{ $t->{sec} }++ }
        }
        elsif ($st eq 'dlg' || $st eq 'desc') {
            # Consecutive rows with the same ID are the lines of ONE entry.
            my $j = $i;
            $j++ while $j + 1 < @T && $T[$j + 1]{st} eq $st && $T[$j + 1]{id} eq $t->{id};

            my $c    = $t->{col};          # Translation column
            my $ecol = $t->{ecol};         # English column
            my @rows = map { my @x = @{ $T[$_]{r} }; push @x, '' while @x <= $c; \@x } $i .. $j;
            my $N    = @rows;

            my $lines = $lines_for->($t->{id});
            if (!$lines) {                 # e.g. CHOICE rows live in labelLUT (a plain string)
                my $v = $label_for->($t->{id});
                $lines = [$v] if defined $v;
            }
            $sec_total{ $t->{sec} }++;

            if (!$lines) {
                $_->[$c] = '' for @rows;
                $missing{$st}++;
                $sec_empty{ $t->{sec} }++;
                (my $src = defined $rows[0][1] ? $rows[0][1] : '') =~ s/\(\d+\)//;   # CHOICE(1) -> CHOICE
                $miss_src{$src}++;
                push @miss_ids, "$t->{id} ($rows[0][1])" if @miss_ids < 8;
            }
            else {
                my $M = @$lines;

                if ($M == $N) {                                  # one line per row
                    $rows[$_][$c] = $lines->[$_] for 0 .. $N - 1;
                }
                elsif ($M < $N) {                                # fewer lines: merge the English rows
                    my $keep = $M - 1;
                    my $eng  = join_english(map { $rows[$_][$ecol] } $keep .. $N - 1);
                    splice @rows, $keep + 1;
                    $rows[$_][$c] = $lines->[$_] for 0 .. $keep;
                    $rows[$keep][$ecol] = $eng;
                    $stat{merged}++;
                    push @ambiguous, "$t->{id} ($N rows -> $M lines)" if $M > 1;
                }
                else {                                           # more lines: extra rows with empty English
                    my @tail = @{ $rows[-1] };
                    $rows[$_][$c] = $lines->[$_] for 0 .. $N - 1;
                    for my $k ($N .. $M - 1) {
                        my @x = @tail;
                        @x[$ecol, $c] = ('', $lines->[$k]);
                        push @rows, \@x;
                    }
                    $stat{extra}++;
                }
            }

            $csv->print($out, $_) for @rows;
            $i = $j + 1;
            next;
        }

        $csv->print($out, \@r);
        $i++;
    }

    warn "Template rows without a translation in the CLD (left empty): $_ = $missing{$_}\n"
        for sort keys %missing;
    if (%miss_src) {
        warn "  left empty, by Source: "
           . join(', ', map { "$_=$miss_src{$_}" } sort { $miss_src{$b} <=> $miss_src{$a} } keys %miss_src) . "\n";
        warn "    e.g. $_\n" for @miss_ids;
    }
    if (%sec_empty) {
        my @s = sort { $sec_empty{$b} <=> $sec_empty{$a} || $a cmp $b } keys %sec_empty;
        warn "Sections with empty translations (empty/entries):\n";
        warn sprintf("    %s: %d/%d\n", $_, $sec_empty{$_}, $sec_total{$_}) for @s[0 .. ($#s < 9 ? $#s : 9)];
    }
    warn "Entries where the template had more English rows than the CLD has lines (rows merged): $stat{merged}\n"
        if $stat{merged};
    if (@ambiguous) {
        warn "  merged with more than one line left (the first lines are matched one-to-one, the rest merged); please check: "
           . scalar(@ambiguous) . "\n";
        warn "    e.g. $_\n" for @ambiguous[0 .. ($#ambiguous < 4 ? $#ambiguous : 4)];
    }
    warn "Entries where the CLD had more lines than the template rows (extra rows added): $stat{extra}\n"
        if $stat{extra};

    for my $t (['lines', $lines_lut], ['labels', $label_lut]) {
        my ($name, $h) = @$t;
        my @unused = grep { !$used{$name}{$_} } sort keys %$h;
        warn "CLD $name entries not found in the template: "
           . scalar(@unused) . " / " . scalar(keys %$h) . "\n";
        warn "  e.g. $_\n" for @unused[0 .. ($#unused < 4 ? $#unused : 4)];
    }
    
    print "Mode: template ($template)\n";
}
else {

    # ---------- Mode B: no template, build the CSV from the CLD only ----------
    info_rows();

    emit('Labels', 'English', 'Translation');
    emit($_, '', $sys_label->{$_}) for sort keys %$sys_label;
    emit();

    emit('Menus', 'Translation');
    emit($_, $sys_menus->{$_}) for sort keys %$sys_menus;
    emit();

    emit('Section', 'labelLUT');
    emit('ID', 'Source', 'English', 'Translation');
    emit($_, '', '', $label_lut->{$_}) for sort keys %$label_lut;
    emit();

    emit('Section', 'linesLUT');
    emit('ID', 'Source', 'English', 'Translation');
    for my $id (sort keys %$lines_lut) {
        my $l = lines_list($lines_lut->{$id});
        $l = [''] unless @$l;
        emit($id, '', '', $_) for @$l;            # one row per line, same ID repeated
    }

    print "Mode: plain (no template; English column is empty and the output is not buildable by the official tool)\n";
}

close $out or die "Failed to save CSV: $!\n";

print "CSV saved: $csv_path\n";
print "All tasks completed!\n";
